package com.example.starter.domain;

/**
 * 观测申请状态。
 */
public enum RequestStatus {

    /** 待批准或候补中：申请已受理，尚未锁定仪器窗口。 */
    PENDING,

    /** 已分配：整段窗口已锁定（管理员批准或候补接替）。 */
    ALLOCATED,

    /** 已撤销：研究组在窗口开始前主动撤销。 */
    CANCELLED
}

package com.example.starter.domain;

/**
 * 幂等调用记录区分的操作类型。
 */
public enum OperationType {

    /** 窗口申请。 */
    APPLY,

    /** 管理员批准（含与已分配窗口冲突的裁决）。 */
    APPROVE,

    /** 研究组撤销（含候补接替）。 */
    CANCEL
}

package com.example.starter.model;

import com.example.starter.domain.RequestStatus;

import java.time.Instant;

/**
 * 观测窗口申请持久化对象。时间均为 UTC，窗口 [{@code windowStart}, {@code windowEnd}) 左闭右开。
 */
public class ObservationRequest {

    private Long id;

    /** 申请编号，候补排序次关键字（升序）。 */
    private String requestNo;

    /** 项目名称。 */
    private String project;

    /** 仪器编号。 */
    private String instrumentId;

    /** 归属研究组，撤销鉴权依据。 */
    private String researchGroup;

    /** 窗口开始时刻（含），UTC。 */
    private Instant windowStart;

    /** 窗口结束时刻（不含），UTC。 */
    private Instant windowEnd;

    /** 所需观测分钟数，取值 1 至窗口分钟数（含边界）。 */
    private int durationMinutes;

    /** 申请状态。 */
    private RequestStatus status;

    /** 申请时间，UTC，候补排序主关键字（升序）。 */
    private Instant requestedAt;

    /** 锁定窗口时间（批准或候补接替），UTC；未分配为 null。 */
    private Instant allocatedAt;

    /** 撤销时间，UTC；未撤销为 null。 */
    private Instant cancelledAt;

    /** 候补接替来源：被撤销申请的编号；直接批准或候补中为 null。 */
    private String promotedFromRequestNo;

    public Long getId() {
        return id;
    }

    public void setId(Long id) {
        this.id = id;
    }

    public String getRequestNo() {
        return requestNo;
    }

    public void setRequestNo(String requestNo) {
        this.requestNo = requestNo;
    }

    public String getProject() {
        return project;
    }

    public void setProject(String project) {
        this.project = project;
    }

    public String getInstrumentId() {
        return instrumentId;
    }

    public void setInstrumentId(String instrumentId) {
        this.instrumentId = instrumentId;
    }

    public String getResearchGroup() {
        return researchGroup;
    }

    public void setResearchGroup(String researchGroup) {
        this.researchGroup = researchGroup;
    }

    public Instant getWindowStart() {
        return windowStart;
    }

    public void setWindowStart(Instant windowStart) {
        this.windowStart = windowStart;
    }

    public Instant getWindowEnd() {
        return windowEnd;
    }

    public void setWindowEnd(Instant windowEnd) {
        this.windowEnd = windowEnd;
    }

    public int getDurationMinutes() {
        return durationMinutes;
    }

    public void setDurationMinutes(int durationMinutes) {
        this.durationMinutes = durationMinutes;
    }

    public RequestStatus getStatus() {
        return status;
    }

    public void setStatus(RequestStatus status) {
        this.status = status;
    }

    public Instant getRequestedAt() {
        return requestedAt;
    }

    public void setRequestedAt(Instant requestedAt) {
        this.requestedAt = requestedAt;
    }

    public Instant getAllocatedAt() {
        return allocatedAt;
    }

    public void setAllocatedAt(Instant allocatedAt) {
        this.allocatedAt = allocatedAt;
    }

    public Instant getCancelledAt() {
        return cancelledAt;
    }

    public void setCancelledAt(Instant cancelledAt) {
        this.cancelledAt = cancelledAt;
    }

    public String getPromotedFromRequestNo() {
        return promotedFromRequestNo;
    }

    public void setPromotedFromRequestNo(String promotedFromRequestNo) {
        this.promotedFromRequestNo = promotedFromRequestNo;
    }
}

package com.example.starter.model;

import java.time.Instant;

/**
 * 撤销触发候补接替的流水。窗口均为 UTC 左闭右开。
 */
public class SuccessionEvent {

    private Long id;

    /** 仪器编号。 */
    private String instrumentId;

    /** 被撤销而让出空档的申请编号。 */
    private String vacatedRequestNo;

    /** 接替空档的候补申请编号。 */
    private String promotedRequestNo;

    /** 空档开始时刻（含），UTC。 */
    private Instant gapStart;

    /** 空档结束时刻（不含），UTC。 */
    private Instant gapEnd;

    /** 接替发生时间，UTC。 */
    private Instant createdAt;

    public Long getId() {
        return id;
    }

    public void setId(Long id) {
        this.id = id;
    }

    public String getInstrumentId() {
        return instrumentId;
    }

    public void setInstrumentId(String instrumentId) {
        this.instrumentId = instrumentId;
    }

    public String getVacatedRequestNo() {
        return vacatedRequestNo;
    }

    public void setVacatedRequestNo(String vacatedRequestNo) {
        this.vacatedRequestNo = vacatedRequestNo;
    }

    public String getPromotedRequestNo() {
        return promotedRequestNo;
    }

    public void setPromotedRequestNo(String promotedRequestNo) {
        this.promotedRequestNo = promotedRequestNo;
    }

    public Instant getGapStart() {
        return gapStart;
    }

    public void setGapStart(Instant gapStart) {
        this.gapStart = gapStart;
    }

    public Instant getGapEnd() {
        return gapEnd;
    }

    public void setGapEnd(Instant gapEnd) {
        this.gapEnd = gapEnd;
    }

    public Instant getCreatedAt() {
        return createdAt;
    }

    public void setCreatedAt(Instant createdAt) {
        this.createdAt = createdAt;
    }
}

package com.example.starter.model;

import com.example.starter.domain.OperationType;
import com.example.starter.domain.RequestStatus;

import java.time.Instant;

/**
 * 幂等调用记录：同一 (requestId, operation) 仅保存首次成功提交的参数指纹与结果。
 */
public class IdempotentCall {

    /** 调用方幂等键。 */
    private String requestId;

    /** 操作类型。 */
    private OperationType operation;

    /** 请求参数指纹（SHA-256 十六进制），与首次不一致返回 409。 */
    private String requestFingerprint;

    /** 首次结果关联的申请编号。 */
    private String resultRequestNo;

    /** 首次结果的申请状态快照。 */
    private RequestStatus resultStatus;

    /** 首次成功提交时间，UTC。 */
    private Instant createdAt;

    public String getRequestId() {
        return requestId;
    }

    public void setRequestId(String requestId) {
        this.requestId = requestId;
    }

    public OperationType getOperation() {
        return operation;
    }

    public void setOperation(OperationType operation) {
        this.operation = operation;
    }

    public String getRequestFingerprint() {
        return requestFingerprint;
    }

    public void setRequestFingerprint(String requestFingerprint) {
        this.requestFingerprint = requestFingerprint;
    }

    public String getResultRequestNo() {
        return resultRequestNo;
    }

    public void setResultRequestNo(String resultRequestNo) {
        this.resultRequestNo = resultRequestNo;
    }

    public RequestStatus getResultStatus() {
        return resultStatus;
    }

    public void setResultStatus(RequestStatus resultStatus) {
        this.resultStatus = resultStatus;
    }

    public Instant getCreatedAt() {
        return createdAt;
    }

    public void setCreatedAt(Instant createdAt) {
        this.createdAt = createdAt;
    }
}

