package com.example.starter.web.dto;

import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

import java.time.Instant;

/**
 * 窗口申请请求体。时间按 UTC 解析，窗口为 [windowStart, windowEnd)。
 */
public record ApplyRequest(
        @NotBlank String project,
        @NotBlank String instrumentId,
        @NotBlank String researchGroup,
        @NotNull Instant windowStart,
        @NotNull Instant windowEnd,
        @Min(1) int durationMinutes,
        String requestId
) {
}

package com.example.starter.web.dto;

/**
 * 管理员批准请求体；requestId 用于批准接口幂等。
 */
public record ApproveRequest(String requestId) {
}

package com.example.starter.web.dto;

import jakarta.validation.constraints.NotBlank;

/**
 * 研究组撤销请求体；requestId 用于撤销接口幂等。
 */
public record CancelRequest(
        @NotBlank String researchGroup,
        String requestId
) {
}

package com.example.starter.web.dto;

import com.example.starter.model.ObservationRequest;

import java.time.Instant;

/**
 * 申请/批准/撤销接口返回的申请视图。
 */
public record RequestView(
        String requestNo,
        String project,
        String instrumentId,
