        assertThat(Fingerprints.sha256("APPLY", "P1", "T", "2026-10-01T20:00:00Z"))
                .isEqualTo(Fingerprints.sha256("APPLY", "P1", "T", "2026-10-01T20:00:00Z"));
    }

