    } catch (org.springframework.dao.DuplicateKeyException e) {
        // 与无共同仪器锁的并发请求竞争同一 requestId：键已被占用，整事务回滚并返回 409。
        throw new ConflictException("requestId=" + requestId + " 已被并发请求占用，"
                + "换参数需使用新的 requestId");
    }
}

